import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"为什么很多人都喜欢浮盈加仓，那样一个反转不是浮亏更快？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/仓位管理/重仓3种方式.md","filePath":"stock/仓位管理/重仓3种方式.md"}'),r={name:"stock/仓位管理/重仓3种方式.md"};function s(n,p,c,i,d,_){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="为什么很多人都喜欢浮盈加仓-那样一个反转不是浮亏更快" tabindex="-1">为什么很多人都喜欢浮盈加仓，那样一个反转不是浮亏更快？ <a class="header-anchor" href="#为什么很多人都喜欢浮盈加仓-那样一个反转不是浮亏更快" aria-label="Permalink to &quot;为什么很多人都喜欢浮盈加仓，那样一个反转不是浮亏更快？&quot;">​</a></h1><p>重仓就三种操作方式。</p><p>第一，浮亏加仓，马上破产。</p><p>第二，开仓即重仓，要不一夜暴富，要不一夜回到解放前。一次成功，多次肯定失败。</p><p>第三，浮盈加仓，最坏结果就是打到成本价或小亏离场。</p><p>你自己选吧。</p><p>要不你就永远轻仓，那就不用考虑加仓问题。</p><hr><p>首先想赚钱还是要重仓的，但是这个重仓跟大家理解的不太一样。分四种：</p><p>直接重仓：这个很好理解，就是一次性大仓位干，赢了会所嫩模，输了工地搬砖，这个用脚后跟想，也不能赚钱，就算赚了，除非你马上停手不干了，否则还是要还回去的。</p><p>间接重仓：这种方式实际上就是我们说的轻仓，但问题是你如果只是轻仓，也不赚钱，所以就发明了累积仓位，最后以一种间接的方式实现重仓，这种做法的好处是每一单都是轻仓，风险敞口小，但会有很多单子，会根据不同周期去介入，逐渐把仓位做大，离场的时候也是同样的顺序，逐渐把各个周期的仓位减掉，整体期望值是正的。</p><p>混合重仓：这种方法一般是第一种和第二种的结合，在趋势刚开始的时候，用轻仓去试单，当底仓成功之后，再进行加仓，但这种方法的问题也很大，有时候会出现刚加仓就频繁打损，导致底仓的浮盈变浮亏。除非你能根据经验判断可能的爆发位置，然后博取很短时间的利润，但这种做法一般都很难，搞不好就爆仓。</p><p>等量重仓：其实也不算是重仓，就是把仓位按一定比例进行计算，然后自己坚持这个比例就行了，之后把行情进行分阶段处理，比如分趋势和震荡，然后根据自己的介入点去下单，这个方法抛弃了底仓和加仓的概念，持仓的单子不多，到目标就走。</p><p>从目前市场和自己的测试看，第二种和第四种表现还可以，但是要对应不同的交易体系才能发挥威力。这里面还有很多其他的工作要做，切不可直接就实盘干，一定要经过大量的练习，并且掌握了它的利弊之后才可以小仓位做。</p>',14)]))}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
